/* Generated by Trae Work */
/* 仪表盘：今日学习计划（进度游标引擎 + 自定义安排；主线任务顺延推进，不绑时段）+ 笔记照片打卡/撤回 + 打卡云端监视（ntfy.sh 实时同步） */
"use strict";
(function () {
  const CLOUD = "https://ntfy.sh";
  const WEEKDAYS = ["周一", "周二", "周三", "周四", "周五", "周六", "周日"];

  function todayISO() {
    const d = new Date(); return fmtDate(d);
  }
  function blockStatus(b) {
    const ov = Store.get("block_overrides", {});
    return ov[b.id] ? ov[b.id].status : "pending";
  }
  function setStatus(b, status, reason) {
    const ov = Store.get("block_overrides", {});
    if (status === "pending") delete ov[b.id];
    else ov[b.id] = {
      status, reason: reason || "",
      done_at: status === "done"
        ? (ov[b.id] && ov[b.id].done_at) || new Date().toLocaleString("zh-CN", { hour12: false })
        : (ov[b.id] && ov[b.id].done_at) || ""
    };
    Store.set("block_overrides", ov);
    if (window.CloudAPI) CloudAPI.queuePush();
  }
  function doneAtOf(b) {
    const ov = Store.get("block_overrides", {});
    return (ov[b.id] && ov[b.id].done_at) || "";
  }

  /* ---------- 自定义课程安排（仅当日生效，存 localStorage） ---------- */
  function customBlocksToday() {
    const m = Store.get("custom_blocks", {});
    return m[todayISO()] || [];
  }
  function addCustomBlock(subject, content_title, start, end, track) {
    const m = Store.get("custom_blocks", {});
    const arr = m[todayISO()] || [];
    arr.push({ id: "custom-" + Date.now().toString(36) + Math.floor(Math.random() * 1e4).toString(36), subject, content_title, start, end, track });
    m[todayISO()] = arr;
    Store.set("custom_blocks", m);
  }
  function delCustomBlock(id) {
    const m = Store.get("custom_blocks", {});
    m[todayISO()] = (m[todayISO()] || []).filter(b => b.id !== id);
    Store.set("custom_blocks", m);
  }

  /* ---------- 今日打卡归档：完成/跳过的游标任务保留到今天结束（监视页与学习端都不掉） ---------- */
  function dayLog() {
    const today = todayISO();
    const l = Store.get("day_log", {});
    if (l.date !== today) { l.date = today; l.entries = []; Store.set("day_log", l); }
    /* 只认游标引擎的任务（u-/custom- 前缀）；旧课表引擎的历史打卡（d-/zk-/ky-/rv- 等）一律清除 */
    const arr = l.entries || [];
    const arr2 = arr.filter(e => {
      const id = String(e.id || "");
      return id.startsWith("u-") || id.startsWith("custom-");
    });
    if (arr2.length !== arr.length) { l.entries = arr2; Store.set("day_log", l); }
    return arr2;
  }
  function logUnitBlock(id, label, time, track, custom, done_at, course) {
    if (!id) return;
    const e = dayLog();
    if (!e.some(x => x.id === id)) {
      e.push({ id, label: label || "", time: time || "", track: track || "", custom: !!custom, done_at: done_at || "", course: course || "", _seq: e.length });
      Store.set("day_log", { date: todayISO(), entries: e });
    }
  }
  function unlogUnitBlock(id) {
    const l = Store.get("day_log", {});
    if (l.date === todayISO()) { l.entries = l.entries.filter(x => x.id !== id); Store.set("day_log", l); }
  }

  /* ---------- 统一课程项（游标任务块 + 自定义块；紧迫度优先；交图完成即从列表消失） ---------- */
  function todayItems() {
    const items = [];
    CursorAPI.todayUnitBlocks().forEach((b, i) => {
      items.push({
        block: b, custom: false,
        time: `约${b.duration_min} 分钟`,
        sortKey: String(i).padStart(2, "0"),
        timeLabel: b._role === "main" ? "主线任务" : "支线任务",
        label: `${CursorAPI.poolLabel(b.subject)} · ${b.content_title}`
      });
    });
    customBlocksToday().forEach(b => {
      items.push({
        block: b, custom: true,
        time: `${b.start}–${b.end}`, sortKey: "9" + b.start,
        timeLabel: "自定义时段",
        label: `${b.subject} · ${b.content_title}`
      });
    });
    /* 完成即消失：列表只留待办；完成的任务经 day_log 进快照，监视端全天可见 */
    return items.filter(v => blockStatus(v.block) !== "done").sort((a, b2) => a.sortKey.localeCompare(b2.sortKey));
  }

  /* ---------- 笔记照片（压缩后经 ntfy.sh 附件上传，随快照保留约 12 小时） ---------- */
  function photoOf(id) {
    const p = Store.get("lesson_photos", {})[id];
    return p && p.date === todayISO() ? p : null;
  }
  function setPhoto(id, url) {
    const m = Store.get("lesson_photos", {});
    m[id] = { date: todayISO(), url, ts: new Date().toLocaleString("zh-CN", { hour12: false }) };
    Store.set("lesson_photos", m);
    if (window.CloudAPI) CloudAPI.queuePush();
  }
  function recallPhoto(id) {
    const m = Store.get("lesson_photos", {});
    delete m[id];
    Store.set("lesson_photos", m);
    if (window.CloudAPI) CloudAPI.queuePush();
  }
  function compressImage(file) {
    return new Promise((res, rej) => {
      const img = new Image();
      img.onload = () => {
        try {
          const max = 1280, scale = Math.min(1, max / Math.max(img.width, img.height));
          const c = document.createElement("canvas");
          c.width = Math.round(img.width * scale); c.height = Math.round(img.height * scale);
          c.getContext("2d").drawImage(img, 0, 0, c.width, c.height);
          c.toBlob(b => b ? res(b) : rej(new Error("压缩失败")), "image/jpeg", 0.72);
        } catch (e) { rej(e); }
      };
      img.onerror = () => rej(new Error("图片读取失败"));
      img.src = URL.createObjectURL(file);
    });
  }
  async function uploadPhoto(topic, blob, name) {
    const res = await fetchTimeout(CLOUD + "/" + topic, {
      method: "POST",
      headers: { "X-Filename": name, "X-Title": "Study Note", "Accept": "application/json" },
      body: blob
    });
    if (!res.ok) throw new Error("HTTP " + res.status);
    const j = await res.json();
    if (!j.attachment || !j.attachment.url) throw new Error("未返回附件地址");
    return j.attachment.url;
  }

  function courseLabelOf(blk) {
    if (!blk) return "";
    if (CursorAPI.isUnitId(blk.id)) return CursorAPI.poolLabel(CursorAPI.parseUnitId(blk.id).code);
    if (String(blk.id).startsWith("rv-")) return CursorAPI.poolLabel(blk.subject);
    return blk.subject || "";
  }

  function buildPayload(items, name) {
    const lessons = items.map(v => {
      const st = blockStatus(v.block);
      const ph = photoOf(v.block.id);
      return {
        id: v.block.id,
        time: v.time,
        label: v.label,
        track: v.block.track,
        course: courseLabelOf(v.block),
        custom: v.custom,
        status: st,
        done_at: st === "done" ? doneAtOf(v.block) : "",
        photos: ph ? [ph.url] : []
      };
    });
    /* 今日归档（完成即消失的任务）继续进快照，监视端全天可见 */
    const ids = new Set(lessons.map(l => l.id));
    dayLog().forEach(e => {
      if (ids.has(e.id)) return;
      const ph = photoOf(e.id);
      lessons.push({
        id: e.id, time: e.time || "—", label: e.label, track: e.track,
        course: e.course || "", custom: e.custom,
        status: "done", done_at: e.done_at || "",
        photos: ph ? [ph.url] : []
      });
    });
    const done = lessons.filter(l => l.status === "done").length;
    const skipped = lessons.filter(l => l.status === "skipped").length;
    return {
      app: "yyy-prep-checkin",
      name: name || "匿名学习者",
      date: todayISO(),
      updated_at: new Date().toLocaleString("zh-CN", { hour12: false }),
      summary: { total: lessons.length, done, skipped, pending: lessons.length - done - skipped, percent: lessons.length ? Math.round(done / lessons.length * 100) : 0 },
      cursors: CursorAPI.cursorState(),
      lessons
    };
  }

  /* ---------- 跨设备进度互通：按身份从云端恢复今日完成状态与照片 ---------- */
  /* 身份：多人拓展接口。单人模式（CHECKIN_CONFIG.multiUser=false）统一用 defaultName，页面不显示昵称输入；改 true 即恢复多人昵称模式 */
  function identity() {
    const cfg = window.CHECKIN_CONFIG || {};
    if (!cfg.multiUser) return cfg.defaultName || "Yyy";
    return Store.get("checkin_name", "").trim() || cfg.defaultName || "Yyy";
  }
  function applySnapshot(snap, items) {
    const ov = Store.get("block_overrides", {});
    const ph = Store.get("lesson_photos", {});
    (snap.lessons || []).forEach(l => {
      const v = items.find(x => x.block.id === l.id) || items.find(x => x.label === l.label && x.time === l.time);
      if (!v) {
        /* 本机窗口外的任务（如跨设备恢复）：完成/跳过的记入今日归档，保证监视页全天可见 */
        if (l.status === "done" || l.status === "skipped") {
          logUnitBlock(l.id, l.label || "", l.time || "", l.track || "", !!l.custom, l.done_at || "", l.course || "");
          if ((l.photos || []).length) {
            const ph = Store.get("lesson_photos", {});
            if (!(ph[l.id] && ph[l.id].date === todayISO())) {
              ph[l.id] = { date: todayISO(), url: l.photos[0], ts: l.done_at || snap.updated_at || "" };
              Store.set("lesson_photos", ph);
            }
          }
        }
        return;
      }
      const b = v.block;
      if (l.status === "pending") delete ov[b.id];
      else ov[b.id] = { status: l.status, reason: (ov[b.id] && ov[b.id].reason) || "", done_at: l.done_at || "" };
      if ((l.photos || []).length && !(ph[b.id] && ph[b.id].date === todayISO())) {
        ph[b.id] = { date: todayISO(), url: l.photos[0], ts: l.done_at || snap.updated_at || "" };
      }
    });
    Store.set("block_overrides", ov);
    Store.set("lesson_photos", ph);
  }
  async function restoreFromCloud(silent) {
    const name = identity();
    try {
      const res = await fetchTimeout(`${CLOUD}/${todayTopic()}/json?poll=1&since=12h`);
      if (!res.ok) throw new Error("HTTP " + res.status);
      const text = await res.text();
      const snaps = [];
      text.trim().split(/\n/).forEach(line => {
        try {
          const m = JSON.parse(line);
          if (m.event !== "message" || !m.message) return;
          const snap = JSON.parse(m.message);
          if (!snap || snap.app !== "yyy-prep-checkin" || (snap.name || "匿名学习者") !== name) return;
          if (snap.date !== todayISO()) return; /* 只恢复今天的快照 */
          snaps.push(snap); /* poll 按时间正序，后一条覆盖，最终为该昵称最新状态 */
        } catch (e) { /* 跳过坏行 */ }
      });
      if (snaps.length) {
        /* 先采纳云端游标（只进不退），再按最终窗口套用完成状态 */
        let cursorChanged = false;
        snaps.forEach(s => { if (s.cursors) cursorChanged = CursorAPI.applyCursorState(s.cursors) || cursorChanged; });
        const items = todayItems();
        snaps.forEach(s => applySnapshot(s, items));
        renderPlan();
        if (!silent) alert(cursorChanged
          ? `已从云端恢复「${name}」的今日进度，并同步了各课学习游标。`
          : `已从云端恢复「${name}」的今日进度。`);
        return true;
      }
      if (!silent) alert("云端 12 小时内没有该昵称的今日打卡记录。");
      return false;
    } catch (e) {
      if (!silent) alert("恢复失败：" + (e.name === "AbortError" ? "请求超时" : e.message));
      return false;
    }
  }

  /* ---------- 云端同步（ntfy.sh 公开频道：免注册、国内可达、SSE 实时；快照保留约 12 小时） ---------- */

  function fetchTimeout(url, opts = {}, ms = 12000) {
    const c = new AbortController();
    const t = setTimeout(() => c.abort(), ms);
    return fetch(url, { ...opts, signal: c.signal }).finally(() => clearTimeout(t));
  }

  function todayTopic() {
    /* 全站共享公共频道（common.js 定义），保证 A/B/C 任意端打卡互相可见 */
    return (window.CHECKIN_TOPIC || "").startsWith("yyy-prep-") ? window.CHECKIN_TOPIC : todayTopicLegacy();
  }
  /* 兼容：未定义公共频道时退回本机私有频道 */
  function todayTopicLegacy() {
    let t = Store.get("checkin_topic", "");
    if (!t) {
      const a = new Uint8Array(10);
      (crypto || {}).getRandomValues ? crypto.getRandomValues(a) : a.forEach((_, i) => a[i] = Math.floor(Math.random() * 256));
      t = "yyy-prep-" + [...a].map(x => x.toString(16).padStart(2, "0")).join("");
      Store.set("checkin_topic", t);
    }
    return t;
  }

  async function pushCloud(silent) {
    const items = todayItems();
    if (!items.length) { if (!silent) alert("今天没有课表块，也没有自定义安排。"); return false; }
    const topic = todayTopic();
    const statusEl = document.getElementById("cloud-status");
    try {
      if (statusEl) statusEl.textContent = "同步中…";
      const res = await fetchTimeout(CLOUD + "/" + topic, {
        method: "POST",
        headers: { "X-Title": "Daily Checkin", "X-Tags": "white_check_mark" },
        body: JSON.stringify(buildPayload(items, identity()))
      });
      if (!res.ok) throw new Error("HTTP " + res.status);
      Store.set("cloud_last_push", new Date().toISOString());
      if (statusEl) statusEl.innerHTML = `<span class="badge ok">已同步</span> 所有人可在 <a href="status.html" target="_blank" rel="noopener">监视页</a> 实时查看`;
      renderCloudPanel();
      return true;
    } catch (e) {
      const msg = e.name === "AbortError" ? "请求超时" : e.message;
      if (statusEl) statusEl.innerHTML = `<span class="badge miss">同步失败</span> ${msg}（可稍后重试）`;
      if (!silent) alert("打卡同步失败：" + msg);
      return false;
    }
  }

  /* ---------- 抽奖动态（A 端学习端）：订阅共享频道，监视端抽中奖金额实时提醒 ---------- */
  let lotteryEs = null;
  function escHtml(s) { return String(s == null ? "" : s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }
  function onLottery(d) {
    const feed = Store.get("lottery_feed", []);
    feed.unshift({ device: d.device || "", amount: d.amount, date: d.date || "", time: d.time || "" });
    Store.set("lottery_feed", feed.slice(0, 5));
    renderLotteryFeed();
    toastMsg(`🎉 监视端抽中 ¥${Number(d.amount).toFixed(2)}！`);
  }
  function renderLotteryFeed() {
    const el = document.getElementById("lottery-feed");
    if (!el) return;
    const feed = Store.get("lottery_feed", []);
    el.innerHTML = feed.length
      ? `<div class="muted" style="font-size:13px;margin-top:8px;"><strong>🎁 最近抽奖动态</strong></div>` + feed.map(f =>
          `<div style="font-size:13px;margin-top:4px;">🎁 ${escHtml(f.date)} ${escHtml(f.time)} · 设备 ${escHtml(String(f.device).slice(0, 9))}… 抽中 <strong style="color:#e63946;">¥${escHtml(Number(f.amount).toFixed(2))}</strong></div>`).join("")
      : "";
  }
  function toastMsg(text) {
    const t = document.createElement("div");
    t.className = "lot-toast";
    t.textContent = text;
    document.body.appendChild(t);
    setTimeout(() => t.remove(), 5000);
  }
  function connectLottery() {
    const topic = todayTopic();
    if (!topic || lotteryEs) return;
    try {
      lotteryEs = new EventSource(`${CLOUD}/${topic}/sse?since=12h`);
      lotteryEs.onmessage = ev => {
        try {
          const m = JSON.parse(ev.data);
          if (m.event !== "message" || !m.message) return;
          const d = JSON.parse(m.message);
          if (d && d.app === "yyy-lottery") onLottery(d);
        } catch (e) { /* 非抽奖消息忽略 */ }
      };
    } catch (e) { /* 网络不可达时静默，不影响打卡功能 */ }
  }

  function renderCloudPanel() {
    const root = document.getElementById("cloud-panel");
    if (!root) return;
    const hasTopic = true; /* 全站共享频道常驻 */
    const last = Store.get("cloud_last_push", "");
    const auto = Store.get("cloud_auto", true);
    const cfg = window.CHECKIN_CONFIG || {};
    root.innerHTML = `
      <h3>打卡监视（云端）</h3>
      <p class="muted">打卡后状态发布到<strong>全站共享频道</strong>（ntfy.sh，SSE 实时推送）；任何人打开<a href="status.html" target="_blank" rel="noopener">监视页</a>即可实时看到最新打卡（快照保留约 12 小时）。仅上传课程完成状态，不含个人隐私。</p>
      <div class="cloud-form">
        ${cfg.multiUser ? `<input id="checkin-name" type="text" placeholder="昵称" value="${Store.get("checkin_name", "")}" maxlength="20">` : ""}
        <button class="btn" id="checkin-now">立即打卡</button>
        <button class="btn ghost" id="cloud-restore" title="拉取云端最新打卡，恢复本机的完成状态与笔记照片">↺ 恢复云端进度</button>
        ${hasTopic ? `<button class="btn ghost" id="cloud-copy">复制监视链接</button>
        <a class="btn ghost" href="status.html" target="_blank" rel="noopener">打开监视页</a>` : ""}
      </div>
      <label style="font-size:13px;display:block;margin-top:8px;"><input type="checkbox" id="cloud-auto" ${auto ? "checked" : ""}> 完成课程时自动同步到云端</label>
      <div id="cloud-status" style="margin-top:8px;font-size:13px;">${hasTopic
        ? (last ? `上次打卡：${new Date(last).toLocaleString("zh-CN", { hour12: false })} · 共享频道已就绪` : "共享频道已就绪，尚未打卡")
        : "共享频道已就绪"}</div>
      <div id="lottery-feed"></div>`;

    renderLotteryFeed();
    document.getElementById("checkin-now").addEventListener("click", () => {
      const ni = document.getElementById("checkin-name");
      if (ni) Store.set("checkin_name", ni.value.trim());
      pushCloud(false);
    });
    document.getElementById("cloud-auto").addEventListener("change", e => Store.set("cloud_auto", e.target.checked));
    document.getElementById("cloud-restore").addEventListener("click", () => {
      const ni = document.getElementById("checkin-name");
      if (ni) Store.set("checkin_name", ni.value.trim());
      restoreFromCloud(false);
    });
    const copy = document.getElementById("cloud-copy");
    if (copy) copy.addEventListener("click", () => {
      const url = location.origin + location.pathname.replace(/[^/]*$/, "") + "status.html";
      (navigator.clipboard ? navigator.clipboard.writeText(url) : Promise.reject()).then(
        () => { copy.textContent = "已复制"; setTimeout(() => copy.textContent = "复制监视链接", 1500); },
        () => prompt("请手动复制监视链接：", url)
      );
    });
  }

  /* ---------- 自定义安排表单 ---------- */
  function toggleCustomForm(show) {
    const f = document.getElementById("custom-form");
    if (f) f.style.display = show ? "block" : "none";
  }
  function customFormHtml() {
    return `
      <div id="custom-form" style="display:none;" class="custom-form">
        <div class="cf-row">
          <input id="cf-subject" type="text" placeholder="课程/事项（如：13180 操作系统、英语单词）" maxlength="30">
          <select id="cf-track">
            <option value="zikao">自考</option>
            <option value="kaoyan">考研</option>
            <option value="custom">通用</option>
          </select>
        </div>
        <input id="cf-content" type="text" placeholder="今天要完成：章节/知识点（如：第2章 进程管理 2.1-2.3）" maxlength="60" style="width:100%;">
        <div class="cf-row">
          <label style="font-size:13px;">开始 <input id="cf-start" type="time" step="300" value="19:00"></label>
          <label style="font-size:13px;">结束 <input id="cf-end" type="time" step="300" value="20:30"></label>
          <button class="btn small" id="cf-save">保存安排</button>
          <button class="btn small ghost" id="cf-cancel">取消</button>
        </div>
      </div>`;
  }
  function bindCustomForm() {
    const root = document.getElementById("today-plan-root");
    if (!root) return;
    const save = document.getElementById("cf-save");
    if (!save) return;
    save.addEventListener("click", () => {
      const subject = document.getElementById("cf-subject").value.trim();
      const content = document.getElementById("cf-content").value.trim();
      const start = document.getElementById("cf-start").value;
      const end = document.getElementById("cf-end").value;
      const track = document.getElementById("cf-track").value;
      if (!subject || !content) return alert("请填写课程/事项与章节内容。");
      if (!start || !end || end <= start) return alert("请检查开始/结束时间。");
      addCustomBlock(subject, content, start, end, track);
      toggleCustomForm(false);
      renderPlan();
      if (Store.get("cloud_auto", true) && Store.get("checkin_topic", "")) pushCloud(true);
    });
    document.getElementById("cf-cancel").addEventListener("click", () => toggleCustomForm(false));
  }

  /* ---------- 游标面板：每课学到哪了 + 考前完成率 + 主线/校准控件 ---------- */
  function cursorPanelHtml() {
    const pool = CursorAPI.coursePool();
    if (!pool.length) return "";
    const main = CursorAPI.mainCourse();
    const rows = pool.map(code => {
      const units = CursorAPI.unitsOf(code);
      const cur = CursorAPI.cursorOf(code);
      const f = CursorAPI.forecast(code);
      const pos = cur < units.length ? units[cur].title : "全部单元已学完";
      const pct = Math.round(cur / Math.max(1, units.length) * 100);
      const exam = CursorAPI.examDateOf(code);
      const paceHtml = f.percentByExam === null
        ? ""
        : (f.onTrack
          ? `预计 <strong>${f.finishDate}</strong> 学完，进度正常`
          : `<strong class="cursor-warn">按当前速度考前约完成 ${f.percentByExam}%，建议加快或校准</strong>`);
      const finished = cur >= units.length;
      return `<div class="cursor-row${code === main ? " is-main" : ""}${finished ? " is-done" : ""}">
        <div class="cursor-name">${CursorAPI.poolLabel(code)}${code === main ? `<span class="badge ok">主线</span>` : ""}${finished ? `<span class="badge ok">已完成</span>` : ""}</div>
        <div class="cursor-mid">
          <div class="prog"><div class="prog-fill" style="width:${pct}%;${finished ? "background:var(--ok,#2fb344);" : ""}"></div></div>
          <div class="cursor-meta">${finished ? `<strong style="color:var(--ok,#2fb344);">100% 全部学完</strong>` : `当前：${pos}（${cur}/${units.length}）`}</div>
        </div>
        <div class="cursor-ops">
          ${code === main ? "" : `<button class="btn small ghost" data-main="${code}">设为主线</button>`}
          ${finished ? "" : `<select class="cursor-cal" data-cal="${code}">
            <option value="">校准游标…</option>
            ${units.map(u => `<option value="${u.idx}">${u.idx === cur ? "▶ " : ""}${u.idx + 1}. ${u.title}</option>`).join("")}
          </select>`}
        </div>
      </div>`;
    }).join("");
    /* 未来 3 天预排：按当前游标确定性预估（只读不落库，今日完成后自动顺延） */
    const WD = ["周日", "周一", "周二", "周三", "周四", "周五", "周六"];
    const prevRows = [1, 2, 3].map(off => {
      const d = new Date(); d.setDate(d.getDate() + off);
      const blocks = CursorAPI.unitBlocksFor(off);
      if (!blocks.length) return "";
      const byCourse = {};
      blocks.forEach(b => {
        const c = CursorAPI.isUnitId(b.id) ? CursorAPI.poolLabel(CursorAPI.parseUnitId(b.id).code) : CursorAPI.poolLabel(b.subject);
        byCourse[c] = (byCourse[c] || 0) + 1;
      });
      return `<div class="pv-row"><strong>${fmtDate(d)}（${WD[d.getDay()]}）</strong>：${Object.entries(byCourse).map(([c, n]) => `${c} × ${n}`).join(" · ")}</div>`;
    }).filter(Boolean).join("");
    return `<div class="cursor-panel">
      <h3>学习进度游标</h3>
      <p class="muted">今日任务由各课游标顺延生成，主线课任务量按「剩余单元 ÷ 距考天数」每天自动倒排；每完成一课须提交该章节笔记照片，上传成功才自动前进（监视端同步可见），跳过则记入跳过。你学到哪里由你校准，网页只负责把计划排顺。</p>
      ${rows}
      ${prevRows ? `<details class="pv-box"><summary>未来 3 天预排（按当前游标预估）</summary>${prevRows}</details>` : ""}
    </div>`;
  }
  function bindCursorControls(root) {
    root.querySelectorAll("button[data-main]").forEach(btn => btn.addEventListener("click", () => {
      CursorAPI.setMainCourse(btn.dataset.main);
      renderPlan();
    }));
    root.querySelectorAll("select.cursor-cal").forEach(sel => sel.addEventListener("change", () => {
      const code = sel.dataset.cal, v = sel.value;
      if (v === "") return;
      const units = CursorAPI.unitsOf(code);
      const u = units[+v];
      if (!u) return;
      if (!confirm(`校准「${CursorAPI.poolLabel(code)}」：此前 ${v} 个单元视为已完成，今天从「${u.title}」开始。确定？`)) return;
      CursorAPI.setCursor(code, +v);
      renderPlan();
      if (Store.get("cloud_auto", true) && Store.get("checkin_topic", "")) pushCloud(true);
    }));
  }

  /* ---------- 今日学习计划 ---------- */
  function renderPlan() {
    const root = document.getElementById("today-plan-root");
    if (!root) return;
    const now = new Date();
    const items = todayItems();
    const doneToday = dayLog().length;
    const totalToday = doneToday + items.length;
    const pct = totalToday ? Math.round(doneToday / totalToday * 100) : 0;

    const head = `
      <div class="plan-summary">
        <div class="plan-date">${now.getMonth() + 1} 月 ${now.getDate()} 日 · ${WEEKDAYS[(now.getDay() + 6) % 7]}</div>
        <div style="display:flex;align-items:center;gap:12px;">
          <button class="btn small ghost" id="custom-add">＋ 自定义安排</button>
          ${doneToday ? `<button class="btn small ghost" id="undo-last">撤回最近一节</button>` : ""}
          <div class="plan-pct">${pct}%<small>（已完成 ${doneToday} 节 · 待完成 ${items.length} 项）</small></div>
        </div>
      </div>
      <div class="prog big"><div class="prog-fill" style="width:${pct}%"></div></div>
      ${cursorPanelHtml()}
      ${customFormHtml()}`;

    if (!items.length) {
      root.innerHTML = head + `<div class="notice empty"><strong>今天没有游标任务与自定义安排。</strong>可在上方「学习进度游标」里校准每门课学到哪了（或在本页下方「学习进度线」选择课程合集），也可点「＋ 自定义安排」添加今日任务。</div>`;
      bindCustomButtons(root);
      bindCursorControls(root);
      document.dispatchEvent(new CustomEvent("heuprep:plan-changed"));
      return;
    }

    const cards = items.map(v => {
      const b = v.block;
      const badgeHtml = v.custom
        ? (b.track === "custom" ? `<span class="badge code">自定义</span>` : badge(b.track))
        : badge(b.track);
      return `
      <div class="plan-lesson ${b.track === "custom" ? "" : b.track}" data-id="${b.id}">
        <div class="pl-head">
          <span class="pl-time">${v.custom ? "自定义" : v.timeLabel}<br><strong>${v.time}</strong></span>
          <div class="pl-goal">
            <div class="pl-goal-label">今天要完成：</div>
            <div class="pl-goal-text">${badgeHtml} ${v.label}</div>
          </div>
          <span class="badge warnb">待完成</span>
        </div>
        <div class="pl-actions">
          <label class="btn small ghost pl-photo-btn">📷 交笔记完成本节<input type="file" accept="image/*" hidden data-photo="${b.id}"></label>
          ${v.custom ? `<button class="btn small ghost" data-delcustom="${b.id}">删除安排</button>` : ""}
        </div>
      </div>`;
    }).join("");

    root.innerHTML = head + cards;
    bindCustomButtons(root);
    bindCursorControls(root);

    /* 撤回最近一节打卡（交错照片的后悔药）：删照片 + 撤销完成 + 游标回退 + 移出归档，监视端同步消失 */
    const undoBtn = root.querySelector("#undo-last");
    if (undoBtn) undoBtn.addEventListener("click", async () => {
      const log = dayLog();
      const last = log[log.length - 1];
      if (!last) return;
      if (!confirm(`撤回最近一节打卡「${last.label || last.id}」？\n照片将删除、完成撤销、游标回退，监视端同步消失。`)) return;
      const uid = last.id;
      recallPhoto(uid);
      if (CursorAPI.isUnitId(uid)) {
        const pu = CursorAPI.parseUnitId(uid);
        if (CursorAPI.cursorOf(pu.code) === pu.idx + 1) CursorAPI.setCursor(pu.code, pu.idx);
      }
      const blk = (items.find(v => v.block.id === uid) || {}).block;
      if (blk) setStatus(blk, "pending");
      unlogUnitBlock(uid);
      renderPlan();
      if (Store.get("cloud_auto", true) && Store.get("checkin_topic", "")) await pushCloud(true);
    });

    /* 删除自定义安排 */
    root.querySelectorAll("button[data-delcustom]").forEach(btn => {
      btn.addEventListener("click", async () => {
        if (!confirm("删除这条自定义安排？")) return;
        delCustomBlock(btn.dataset.delcustom);
        renderPlan();
        if (Store.get("cloud_auto", true) && Store.get("checkin_topic", "")) await pushCloud(true);
      });
    });

    /* 笔记照片：压缩上传后自动完成该节打卡 */
    root.querySelectorAll("input[data-photo]").forEach(inp => {
      inp.addEventListener("change", async () => {
        const id = inp.dataset.photo;
        const f = inp.files && inp.files[0];
        if (!f) return;
        const blk = (items.find(v => v.block.id === id) || {}).block;
        const st = document.getElementById("cloud-status");
        try {
          if (st) st.textContent = "笔记照片上传中…";
          const blob = await compressImage(f);
          const fname = "note-" + id.replace(/[^a-zA-Z0-9]/g, "") + "-" + Date.now() + ".jpg";
          /* 已配置云存档时走 GitHub 图床（永久保存），否则走 ntfy（12 小时） */
          const url = (window.CloudAPI && CloudAPI.configured())
            ? await CloudAPI.uploadImage(blob, fname)
            : await uploadPhoto(todayTopic(), blob, fname);
          setPhoto(id, url);
          if (blk) setStatus(blk, "done");
          if (blk && CursorAPI.isUnitId(id)) {
            const pu = CursorAPI.parseUnitId(id);
            CursorAPI.markUnitDone(pu.code, pu.idx);
          }
          if (st) st.innerHTML = `<span class="badge ok">笔记已上传，已完成该节打卡</span>`;
          {
            const v = items.find(x => x.block.id === id);
            logUnitBlock(id, v ? v.label : id, v ? v.time : "", blk ? blk.track : "", !!v && v.custom, blk ? doneAtOf(blk) : "", blk ? courseLabelOf(blk) : "");
          }
          renderPlan();
          if (Store.get("cloud_auto", true) && Store.get("checkin_topic", "")) await pushCloud(true);
        } catch (e) {
          const msg = e.name === "AbortError" ? "请求超时" : e.message;
          if (st) st.innerHTML = `<span class="badge miss">笔记上传失败</span> ${msg}（可稍后重试）`;
        }
      });
    });
    document.dispatchEvent(new CustomEvent("heuprep:plan-changed"));
  }

  function bindCustomButtons(root) {
    const add = root.querySelector("#custom-add");
    if (add) add.addEventListener("click", () => {
      const f = document.getElementById("custom-form");
      toggleCustomForm(!f || f.style.display === "none");
    });
    bindCustomForm();
  }

  /* ---------- 课程设置：自考选科 / 考研合集 / 主线课程 / 清空记录 ---------- */
  function renderSettings() {
    const zkList = document.getElementById("zk-subject-list");
    if (zkList) {
      const selectable = SITE_DATA.zikao.courses.filter(c => c.chapters || c.reference_chapters);
      const sel = Store.get("zk_subjects", []);
      zkList.innerHTML = selectable.map(c => `
        <label class="check-item"><input type="checkbox" value="${c.code}" ${sel.includes(c.code) ? "checked" : ""}>
          ${c.code} ${c.name}<span class="muted">（${(c.chapters || (c.reference_chapters && c.reference_chapters.chapters) || []).length} 个单元）</span></label>`).join("");
      const save = document.getElementById("zk-subject-save");
      if (save) save.addEventListener("click", () => {
        const picked = [...zkList.querySelectorAll("input:checked")].map(i => i.value);
        if (picked.length && picked.length < 2) { alert("自考选科至少 2 门（或全部不选，只学考研科目）。"); return; }
        if (picked.length > 4) { alert("自考选科最多 4 门。"); return; }
        Store.set("zk_subjects", picked);
        const cur = Store.get("main_course", "");
        if (cur && !picked.includes(cur) && !["数二", "英二", "408"].includes(cur)) Store.set("main_course", "");
        alert("自考选科已保存，进度线已更新。");
        renderPlan(); renderSettings();
      });
    }
    const kyList = document.getElementById("ky-subject-list");
    if (kyList) {
      const all = ["数二", "英二", "408"];
      const names = { "数二": "数学（二）", "英二": "英语（二）", "408": "408 计算机学科专业基础综合" };
      const sel = Store.get("ky_subjects", all.slice());
      kyList.innerHTML = all.map(c => `
        <label class="check-item"><input type="checkbox" value="${c}" ${sel.includes(c) ? "checked" : ""}>${names[c]}</label>`).join("");
      const save = document.getElementById("ky-subject-save");
      if (save) save.addEventListener("click", () => {
        const picked = [...kyList.querySelectorAll("input:checked")].map(i => i.value);
        if (!picked.length) { alert("考研科目合集至少保留 1 门。"); return; }
        Store.set("ky_subjects", picked);
        const cur = Store.get("main_course", "");
        if (cur && !picked.includes(cur) && !SITE_DATA.zikao.courses.some(x => x.code === cur)) Store.set("main_course", "");
        alert("考研合集已保存，进度线已更新。");
        renderPlan(); renderSettings();
      });
    }
    const priSel = document.getElementById("priority-select");
    if (priSel) {
      const pool = CursorAPI.coursePool();
      const cur = CursorAPI.mainCourse();
      priSel.innerHTML = `<option value="">不设主线（按紧迫度自动）</option>` +
        pool.map(c => `<option value="${c}" ${c === cur ? "selected" : ""}>${CursorAPI.poolLabel(c)}</option>`).join("");
      const save = document.getElementById("priority-save");
      if (save) save.addEventListener("click", () => {
        CursorAPI.setMainCourse(priSel.value);
        alert("主线课程已保存，今日任务量已按新主线重排。");
        renderPlan();
      });
    }
    const reset = document.getElementById("sch-reset");
    if (reset && !reset.dataset.bound) {
      reset.dataset.bound = "1";
      reset.addEventListener("click", () => {
        if (!confirm("确定清空所有进度线本地记录？各课游标归零、完成记录清空，需重新校准。选科与主线设置保留。")) return;
        ["course_cursor", "cursor_history", "skipped_units", "block_overrides", "day_log", "lesson_photos", "custom_blocks"].forEach(k => Store.set(k, k === "lesson_photos" || k === "custom_blocks" ? {} : (k === "day_log" ? { date: "", entries: [] } : {})));
        alert("已清空。请逐科重新校准游标。");
        renderPlan();
      });
    }
  }

  document.addEventListener("DOMContentLoaded", async () => {
    if (!document.getElementById("today-plan-root")) return;
    renderPlan();
    renderSettings();
    renderCloudPanel();
    /* 跨设备互通：本机填过昵称时，进页先按昵称恢复云端最新进度 */
    if (Store.get("checkin_name", "").trim()) await restoreFromCloud(true);
    /* 开自动同步：进页静默同步一次（全站共享频道常驻） */
    if (Store.get("cloud_auto", true)) pushCloud(true);
    /* 抽奖动态：实时接收监视端抽奖结果 */
    connectLottery();
    /* 补推：打卡时若推送失败（网络抖动/息屏），回到前台自动补推一次，保证监视端及时看到 */
    document.addEventListener("visibilitychange", () => {
      if (document.visibilityState === "visible" && Store.get("cloud_auto", true)) pushCloud(true);
    });
    const refresh = document.getElementById("plan-refresh");
    if (refresh) refresh.addEventListener("click", renderPlan);
  });
})();
